// app/src/shell/index.test.tsx
import React from 'react';
import { render, screen, cleanup } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe, toHaveNoViolations } from 'jest-axe';
import { AppShell } from './index';
import { expect, it, describe, afterEach, beforeEach, vi } from 'vitest';
vi.mock('@antv/x6', () => ({ Graph: vi.fn() }));
vi.mock('../views/acoustics/CalculatorsDrawer', () => ({ CalculatorsDrawer: () => <div data-testid="calculators-drawer"></div> }));
vi.mock('../views/canvas/CanvasView', () => ({ CanvasView: () => <div data-testid="canvas-view">Canvas</div> }));
import '../locales/i18n';

expect.extend(toHaveNoViolations);


beforeEach(() => {
  vi.stubGlobal('fetch', vi.fn().mockResolvedValue({
    ok: true,
    json: async () => ({
      namespace: 'test',
      actor: 'test-user',
      // And for the topology call:
      designLabel: 'test',
      revision: '1',
      sites: [], locations: [], racks: [], deviceTypes: [], devices: [], cables: [], signalClasses: []
    })
  }));
});

afterEach(() => {
  cleanup();
});

describe('AppShell', () => {
  it('renders the layout and navigation with correct translations', async () => {
    render(React.createElement(AppShell));
    const homeLinks = await screen.findAllByText('Canvas');
    expect(homeLinks.length).toBeGreaterThan(0);
  });

  it('is keyboard operable via tabbing', async () => {
    const user = userEvent.setup();
    render(React.createElement(AppShell));
    const homeLinks = await screen.findAllByText('Canvas');
    const homeLink = homeLinks[0];
    
    // Start at document body
    await user.tab();
    expect(document.activeElement).toBe(homeLink);
  });

  it('has no a11y violations', async () => {
    const { container } = render(React.createElement(AppShell));
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });
});

import { ReactNode, createContext, useContext, useEffect, useState } from 'react';
import { BrowserRouter, Routes, Route, Link, useLocation } from 'react-router-dom';

import { useDocumentStore } from '../store/documentStore';
import { useSettingsStore } from '../store/settingsStore';
import { ErrorState } from './error-state';
import { CanvasView } from '../views/canvas/CanvasView';
import { RackElevationView } from '../views/rack/RackElevationView';
import { CableScheduleView } from '../views/cable-schedule/CableScheduleView';
import { SceneView } from '../views/scene/SceneView';
import { DsarSurface } from '../components/compliance/DsarSurface';
import { SettingsPanel } from '../views/canvas/SettingsPanel';
import { BomView } from '../views/bom/BomView';

import fixtureReferenceProject from '../../tests/fixtures/reference-projects/AV_U1A21.project.json';
import { bffClient } from '../api/client';
import { LoadingState } from './loading-state';
import { readProjectSchema } from '../exchange/projectschema/read';
import { toX6 } from '../projection/toX6';
import { applyElkLayoutX6 } from '../projection/layout';

interface SessionContextType {
  tenantId: string;
  userId: string;
}

const SessionContext = createContext<SessionContextType | null>(null);

function NavItem({ to, label }: { to: string; label: string }) {
  const location = useLocation();
  const isActive = location.pathname === to;
  return (
    <li>
      <Link to={to} className={isActive ? 'active' : ''}>
        {label}
      </Link>
    </li>
  );
}

import { useTranslation } from 'react-i18next';

function Layout({ children }: { children: ReactNode }) {
  const { t } = useTranslation();
  const session = useContext(SessionContext);
  const isSaving = useDocumentStore(state => state.isSaving);
  const syncConflict = useDocumentStore(state => state.syncConflict);
  const saveDocument = useDocumentStore(state => state.saveDocument);
  const document = useDocumentStore(state => state.document);

  const handleSave = async () => {
    if (!session || !document) return;
    await saveDocument(bffClient, session.tenantId, session.userId);
  };

  const handleReload = () => {
    window.location.reload();
  };

  return (
    <div className="app-layout">
      <nav className="m3-nav-drawer">
        <div className="m3-nav-header">Copper</div>
        <ul>
          <NavItem to="/" label={t('nav.canvas')} />
          <NavItem to="/rack" label={t('nav.rack')} />
          <NavItem to="/schedule" label={t('nav.schedule')} />
          <NavItem to="/3d" label={t('nav.walkthrough')} />
          <NavItem to="/bom" label={t('nav.bom')} />
          <NavItem to="/compliance" label={t('nav.compliance')} />
        </ul>
        <div className="session-info">
          {session?.tenantId} • {session?.userId}
        </div>
      </nav>
      <main className="m3-main-content">
        <header style={{ padding: '8px 16px', display: 'flex', justifyContent: 'flex-end', alignItems: 'center', gap: '16px', borderBottom: '1px solid var(--md-sys-color-outline-variant)', backgroundColor: 'var(--md-sys-color-surface)' }}>
          {syncConflict && (
            <div style={{ color: 'var(--md-sys-color-error)', display: 'flex', alignItems: 'center', gap: '8px' }}>
              <span>Version Conflict!</span>
              <button onClick={handleReload} className="m3-button">Reload & Reapply</button>
            </div>
          )}
          <button disabled={isSaving || syncConflict || !document} onClick={handleSave} className="m3-button">
            {isSaving ? 'Saving...' : 'Save Design'}
          </button>
        </header>
        {children}
      </main>
    </div>
  );
}

export function ConnectedCanvasView() {
  const document = useDocumentStore(state => state.document);
  const settings = useSettingsStore();
  const [nodes, setNodes] = useState<any[]>([]);
  const [edges, setEdges] = useState<any[]>([]);

  useEffect(() => {
    if (!document) return;
    const { nodes: rawNodes, edges: rawEdges } = toX6(document, {}, {
      terminalSpacing: settings.terminalSpacing,
      headerHeight: settings.headerFontSize + 14
    });

    applyElkLayoutX6(rawNodes, rawEdges, { wireSpacing: settings.wireSpacing, portPadding: settings.portPadding }).then(({ nodes: layoutedNodes, edges: layoutedEdges }) => {
      setNodes(layoutedNodes);
      setEdges(layoutedEdges);
    });
  }, [document, settings.wireSpacing, settings.portPadding, settings.terminalSpacing, settings.headerFontSize, settings.showCableLabels, settings.cableLabelPosition]);

  const cssVars = {
    '--copper-terminal-spacing': `${settings.terminalSpacing}px`,
    '--copper-terminal-font-size': `${settings.terminalFontSize}px`,
    '--copper-header-font-size': `${settings.headerFontSize}px`,
    '--copper-header-height': `${settings.headerFontSize + 14}px`,
  } as React.CSSProperties;

  if (!document) return <div style={{padding: '2rem'}}>Loading document...</div>;
  return (
    <div style={{ width: '100%', height: '100%', position: 'relative', ...cssVars }}>
      <SettingsPanel />
      <CanvasView nodes={nodes} edges={edges} enableWiring={true} />
    </div>
  );
}

function ConnectedRackElevationView() {
  const document = useDocumentStore(state => state.document);
  if (!document) return <div style={{padding: '2rem'}}>Loading document...</div>;
  const firstRackId = document.racks[0]?.id ?? '';
  const geometryMap = {};
  return <RackElevationView doc={document} geometryMap={geometryMap} selectedRackId={firstRackId} />;
}

function ConnectedCableScheduleView() {
  const document = useDocumentStore(state => state.document);
  if (!document) return <div style={{padding: '2rem'}}>Loading document...</div>;
  return <CableScheduleView document={document} />;
}

export function AppShell() {
  const [session, setSession] = useState<SessionContextType | null>(null);
  const [error, setError] = useState<any>(null);
  const loadDocument = useDocumentStore(state => state.loadDocument);
  const document = useDocumentStore(state => state.document);

  const boot = async () => {
    try {
      setError(null);
      const sessionRes = await fetch('/api/session');
      if (!sessionRes.ok) throw new Error(`Auth failed: ${sessionRes.status}`);
      const sessionData = await sessionRes.json();
      const sess = { tenantId: sessionData.namespace, userId: sessionData.actor };
      setSession(sess);

      if ((import.meta as any).env.VITE_COPPER_FIXTURE === '1') {
        const { document: parsedDoc } = readProjectSchema(fixtureReferenceProject as any);
        loadDocument(parsedDoc);
      } else {
        const docRes = await fetch(`/api/design/topology?namespace_id=${sess.tenantId}`);
        if (!docRes.ok) throw new Error(`Failed to load design: ${docRes.status}`);
        const parsedDoc = await docRes.json();
        loadDocument(parsedDoc);
      }
    } catch (e: any) {
      setError(e);
    }
  };

  useEffect(() => {
    if (!document) {
      boot();
    }
  }, [document, loadDocument]);

  if (error) return <ErrorState error={error} onRetry={boot} />;
  if (!session || !document) return <LoadingState />;

  return (
    <SessionContext.Provider value={session}>
      <BrowserRouter>
        <Layout>
          <Routes>
            <Route path="/" element={<ConnectedCanvasView />} />
            <Route path="/rack" element={<ConnectedRackElevationView />} />
            <Route path="/schedule" element={<ConnectedCableScheduleView />} />
            <Route path="/3d" element={<SceneView />} />
            <Route path="/bom" element={<BomView />} />
            <Route path="/compliance" element={<div style={{padding: '2rem'}}><DsarSurface /></div>} />
            <Route path="*" element={<ErrorState error={{ code: -32005 }} />} />
          </Routes>
        </Layout>
      </BrowserRouter>
    </SessionContext.Provider>
  );
}

import React, { useState, useMemo } from 'react';
import { useTranslation, Trans } from 'react-i18next';
import {
  speedOfSound, wavelength, period,
  delayFromDistance, distanceFromDelay,
  phaseFromDelay, delayFromPhase,
  airAbsorption, airAbsorptionDb,
  floorBounce, logFrequencyGrid,
  getLR24, evaluateCascade
} from '@copper/acoustics';

const fmt = (n: number, digits: number) => n.toFixed(digits);

export const CalculatorsDrawer: React.FC = () => {
  const { t } = useTranslation();
  const [isOpen, setIsOpen] = useState(false);

  // Environment
  const [T_C, setT_C] = useState(20);
  const [RH, setRH] = useState(50);
  const [p_atm, setP_atm] = useState(101325);
  const c = useMemo(() => speedOfSound(T_C, RH, p_atm), [T_C, RH, p_atm]);

  // Wavelength / period
  const [freq, setFreq] = useState(1000);
  const lambda = useMemo(() => wavelength(freq, c), [freq, c]);
  const periodMs = useMemo(() => period(freq) * 1000, [freq]);

  // Distance / delay
  const [distM, setDistM] = useState(10);
  const delayMs = useMemo(() => delayFromDistance(distM, c) * 1000, [distM, c]);
  const [delayInput, setDelayInput] = useState(10);
  const distFromDelay = useMemo(() => distanceFromDelay(delayInput / 1000, c), [delayInput, c]);


  // DSP
  const [xoFreq, setXoFreq] = useState(100);
  const [xoEvalFreq, setXoEvalFreq] = useState(100);
  const xoAtten = useMemo(() => {
    try {
      const cascade = getLR24('lpf', xoFreq, 48000);
      const h = evaluateCascade(cascade, xoEvalFreq, 48000);
      const mag = Math.sqrt(h.re*h.re + h.im*h.im);
      return mag > 0 ? 20 * Math.log10(mag) : -100;
    } catch { return 0; }
  }, [xoFreq, xoEvalFreq]);

  // Phase / delay
  const [phaseFreq, setPhaseFreq] = useState(1000);
  const [phaseDelayMs, setPhaseDelayMs] = useState(1);
  const phaseDeg = useMemo(() => phaseFromDelay(phaseDelayMs / 1000, phaseFreq), [phaseDelayMs, phaseFreq]);
  const [phaseInputDeg, setPhaseInputDeg] = useState(180);
  const delayFromPhaseMs = useMemo(() => delayFromPhase(phaseInputDeg, phaseFreq) * 1000, [phaseInputDeg, phaseFreq]);

  // Air absorption
  const [absorbDist, setAbsorbDist] = useState(30);
  const absorbBands = [125, 250, 500, 1000, 2000, 4000, 8000, 16000];
  const absorbRows = useMemo(() => absorbBands.map((f) => ({
    f,
    alpha: airAbsorption(f, T_C, RH, p_atm),
    dB: airAbsorptionDb(f, absorbDist, T_C, RH, p_atm),
  })), [absorbBands, T_C, RH, p_atm, absorbDist]);

  // Floor bounce
  const [fbDist, setFbDist] = useState(4);
  const [fbSrcH, setFbSrcH] = useState(1.2);
  const [fbMicH, setFbMicH] = useState(1.2);
  const [fbReflect, setFbReflect] = useState(0.8);
  
  const fbPath = useMemo(() => {
    const fbGrid = logFrequencyGrid(50, 20000, 120);
    const fbSamples = fbGrid.map((f) => ({
      f,
      db: floorBounce(f, fbDist, fbSrcH, fbMicH, fbReflect, c),
    }));
    const fMin = Math.log10(fbGrid[0]!);
    const fMax = Math.log10(fbGrid[fbGrid.length - 1]!);
    const xOf = (f: number) => ((Math.log10(f) - fMin) / (fMax - fMin)) * 600;
    const yOf = (db: number) => -db; // 1 px per dB, centre at 0
    return fbSamples.map((s, i) => (i === 0 ? 'M' : 'L') + xOf(s.f).toFixed(1) + ',' + yOf(s.db).toFixed(1)).join(' ');
  }, [fbDist, fbSrcH, fbMicH, fbReflect, c]);

  if (!isOpen) {
    return (
      <button 
        className="m3-button" 
        style={{ position: 'absolute', bottom: 16, right: 16, zIndex: 10 }} 
        onClick={() => setIsOpen(true)}
      >
        Calculators
      </button>
    );
  }

  return (
    <div style={{ position: 'absolute', right: 16, bottom: 60, width: 400, height: 600, overflow: 'auto', zIndex: 10, background: 'var(--copper-surface)', border: '1px solid var(--copper-outline)', padding: 16, borderRadius: 8, boxShadow: 'var(--md-sys-elevation-level-3)' }}>
      <button className="m3-button m3-button-text" onClick={() => setIsOpen(false)} style={{ float: 'right' }}>X</button>
      <div className="m3-content-padding" style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
      <div className="m3-card m3-content-padding">
        <h2>{t('acoustics.title')}</h2>
        <p>
          <Trans i18nKey="acoustics.credit">
            These calculators are based on the work of <a href="https://www.merlijnvanveen.nl/en/calculators" target="_blank" rel="noopener">Merlijn van Veen</a>.
            The original Excel spreadsheets are freely available on his website; this panel re-implements the same formulae in TypeScript so they can feed the design tool and be unit-tested. Credit for pulling these formulae together into accessible calculators belongs to Merlijn van Veen.
          </Trans>
        </p>
      </div>

      <div className="m3-card m3-content-padding">
        <h3>{t('acoustics.environment')}</h3>
        <div style={{ display: 'flex', gap: '16px', flexWrap: 'wrap' }}>
          <label style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
            {t('acoustics.temp')}
            <input type="number" step="0.5" value={T_C} onChange={(e) => setT_C(Number(e.target.value))} />
          </label>
          <label style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
            {t('acoustics.rh')}
            <input type="number" step="1" min="0" max="100" value={RH} onChange={(e) => setRH(Number(e.target.value))} />
          </label>
          <label style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
            {t('acoustics.pressure')}
            <input type="number" step="100" value={p_atm} onChange={(e) => setP_atm(Number(e.target.value))} />
          </label>
        </div>
        <p style={{ marginTop: '16px', fontWeight: 'bold' }}>
          {t('acoustics.speed')} c = {fmt(c, 2)} m/s
        </p>
      </div>

      <div className="m3-card m3-content-padding">
        <h3>{t('acoustics.wavelength_period')}</h3>
        <div style={{ display: 'flex', gap: '16px', alignItems: 'center' }}>
          <label style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
            {t('acoustics.frequency')}
            <input type="number" step="1" value={freq} onChange={(e) => setFreq(Number(e.target.value))} />
          </label>
          <div>
            λ = <strong>{fmt(lambda * 100, 2)} cm</strong>
            &nbsp;·&nbsp;
            T = <strong>{fmt(periodMs, 3)} ms</strong>
          </div>
        </div>
      </div>

      <div className="m3-card m3-content-padding">
        <h3>{t('acoustics.dist_delay')}</h3>
        <div style={{ display: 'flex', gap: '32px', flexWrap: 'wrap' }}>
          <div style={{ display: 'flex', gap: '16px', alignItems: 'center' }}>
            <label style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
              {t('acoustics.distance')}
              <input type="number" step="0.1" value={distM} onChange={(e) => setDistM(Number(e.target.value))} />
            </label>
            <div>delay = <strong>{fmt(delayMs, 2)} ms</strong></div>
          </div>
          <div style={{ display: 'flex', gap: '16px', alignItems: 'center' }}>
            <label style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
              {t('acoustics.delay')}
              <input type="number" step="0.1" value={delayInput} onChange={(e) => setDelayInput(Number(e.target.value))} />
            </label>
            <div>dist = <strong>{fmt(distFromDelay, 2)} m</strong></div>
          </div>
        </div>
      </div>

      <div className="m3-card m3-content-padding">
        <h3>{t('acoustics.phase_delay')}</h3>
        <div style={{ display: 'flex', gap: '32px', flexWrap: 'wrap' }}>
          <div style={{ display: 'flex', gap: '16px', alignItems: 'center' }}>
            <label style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
              {t('acoustics.frequency')}
              <input type="number" step="1" value={phaseFreq} onChange={(e) => setPhaseFreq(Number(e.target.value))} />
            </label>
            <label style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
              {t('acoustics.delay')}
              <input type="number" step="0.1" value={phaseDelayMs} onChange={(e) => setPhaseDelayMs(Number(e.target.value))} />
            </label>
            <div>phase = <strong>{fmt(phaseDeg, 1)}°</strong></div>
          </div>
          <div style={{ display: 'flex', gap: '16px', alignItems: 'center' }}>
            <label style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
              {t('acoustics.frequency')}
              <input type="number" step="1" value={phaseFreq} onChange={(e) => setPhaseFreq(Number(e.target.value))} />
            </label>
            <label style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
              {t('acoustics.phase')}
              <input type="number" step="5" value={phaseInputDeg} onChange={(e) => setPhaseInputDeg(Number(e.target.value))} />
            </label>
            <div>delay = <strong>{fmt(delayFromPhaseMs, 3)} ms</strong></div>
          </div>
        </div>
        <p style={{ opacity: 0.7, marginTop: '8px', fontSize: '0.875rem' }}>
          {t('acoustics.phase_sign')}
        </p>
      </div>

      <div className="m3-card m3-content-padding">
        <h3>{t('acoustics.air_absorption')}</h3>
        <div style={{ display: 'flex', gap: '16px', alignItems: 'center', marginBottom: '16px' }}>
          <label style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
            {t('acoustics.prop_distance')}
            <input type="number" step="1" value={absorbDist} onChange={(e) => setAbsorbDist(Number(e.target.value))} />
          </label>
          <div style={{ opacity: 0.7, fontSize: '0.875rem' }}>
            At {T_C} °C, {RH}% RH, {(p_atm / 1000).toFixed(1)} kPa.
          </div>
        </div>
        <table style={{ width: '100%', textAlign: 'left', borderCollapse: 'collapse' }}>
          <thead>
            <tr>
              <th style={{ padding: '8px', borderBottom: '1px solid var(--md-sys-color-outline-variant)' }}>f (Hz)</th>
              <th style={{ padding: '8px', borderBottom: '1px solid var(--md-sys-color-outline-variant)' }}>α (dB/m)</th>
              <th style={{ padding: '8px', borderBottom: '1px solid var(--md-sys-color-outline-variant)' }}>Loss at {absorbDist} m (dB)</th>
            </tr>
          </thead>
          <tbody>
            {absorbRows.map((r) => (
              <tr key={r.f}>
                <td style={{ padding: '8px', borderBottom: '1px solid var(--md-sys-color-outline-variant)' }}>{r.f}</td>
                <td style={{ padding: '8px', borderBottom: '1px solid var(--md-sys-color-outline-variant)' }}>{fmt(r.alpha, 4)}</td>
                <td style={{ padding: '8px', borderBottom: '1px solid var(--md-sys-color-outline-variant)' }}>{fmt(r.dB, 2)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div className="m3-card m3-content-padding">
        <h3>{t('acoustics.floor_bounce')}</h3>
        <div style={{ display: 'flex', gap: '16px', flexWrap: 'wrap', marginBottom: '16px' }}>
          <label style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
            {t('acoustics.hz_dist')}
            <input type="number" step="0.1" value={fbDist} onChange={(e) => setFbDist(Number(e.target.value))} />
          </label>
          <label style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
            {t('acoustics.src_height')}
            <input type="number" step="0.1" value={fbSrcH} onChange={(e) => setFbSrcH(Number(e.target.value))} />
          </label>
          <label style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
            {t('acoustics.mic_height')}
            <input type="number" step="0.1" value={fbMicH} onChange={(e) => setFbMicH(Number(e.target.value))} />
          </label>
          <label style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
            {t('acoustics.reflection')}
            <input type="number" step="0.1" min="0" max="1" value={fbReflect} onChange={(e) => setFbReflect(Number(e.target.value))} />
          </label>
        </div>
        <svg viewBox="0 -24 600 48" style={{ width: '100%', maxWidth: '600px', background: 'var(--md-sys-color-surface-container-high)', borderRadius: '8px', border: '1px solid var(--md-sys-color-outline-variant)' }}>
          <line x1="0" y1="0" x2="600" y2="0" stroke="var(--md-sys-color-outline)" strokeWidth="1" />
          <path d={fbPath} fill="none" stroke="var(--md-sys-color-primary)" strokeWidth="2" />
        </svg>
      </div>
      <div className="m3-card m3-content-padding">
        <h3>DSP & Crossovers (LR-24)</h3>
        <div style={{ display: 'flex', gap: '16px', flexWrap: 'wrap', marginBottom: '16px' }}>
          <label style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
            Cutoff Freq (Hz)
            <input className="m3-input" type="number" value={xoFreq} onChange={e => setXoFreq(Number(e.target.value) || 100)} />
          </label>
          <label style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
            Eval Freq (Hz)
            <input className="m3-input" type="number" value={xoEvalFreq} onChange={e => setXoEvalFreq(Number(e.target.value) || 100)} />
          </label>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '4px', justifyContent: 'flex-end' }}>
            <strong style={{ display: 'block', paddingBottom: '4px' }}>{fmt(xoAtten, 2)} dB</strong>
          </div>
        </div>
      </div>
    </div>
    </div>
  );
};

import { useState, useEffect, useMemo, useRef } from 'react';
import { useDocumentStore } from '../../store/documentStore';
import { generateArrayPreset, ArrayPreset, computePolar, computeHeatmap } from '@copper/acoustics';
import { useTranslation } from 'react-i18next';

export function SubArrayPanel() {
  const { t } = useTranslation();
  const document = useDocumentStore(state => state.document);
  const updateDocument = useDocumentStore(state => state.updateDocument);
  const [isOpen, setIsOpen] = useState(false);

  const [preset, setPreset] = useState<ArrayPreset>('Endfire');
  const [count, setCount] = useState<number>(4);
  const [freq, setFreq] = useState<number>(60);
  const [amplitudeShading, setAmplitudeShading] = useState(false);
  const [delayTapering, setDelayTapering] = useState<number | ''>('');
  const [spacing, setSpacing] = useState<number | ''>(''); // empty means auto
  const [selectedSubId, setSelectedSubId] = useState<string>('');

  const canvasRef = useRef<HTMLCanvasElement>(null);

  // Filter device types to likely subwoofers (or any speaker)
  const availableSubs = useMemo(() => {
    if (!document) return [];
    return document.deviceTypes.filter(dt => {
      // Basic heuristic: it's a speaker
      const acoustics = dt.customFields?.acoustics as { device_class?: string } | undefined;
      return acoustics?.device_class === 'speaker';
    });
  }, [document]);

  useEffect(() => {
    if (availableSubs.length > 0 && !selectedSubId) {
      setSelectedSubId(availableSubs[0]?.id || '');
    }
  }, [availableSubs, selectedSubId]);

  const sources = useMemo(() => {
    const s = spacing === '' ? undefined : spacing;
    return generateArrayPreset(preset, count, freq, s, { amplitudeShading, ...(delayTapering ? { delayTaperingSplayDeg: delayTapering } : {}) });
  }, [preset, count, freq, spacing]);

  const polarData = useMemo(() => {
    // 1000m radius for far-field plane wave approximation
    return computePolar(sources, freq, 10000, 2);
  }, [sources, freq]);

  useEffect(() => {
    const cvs = canvasRef.current;
    if (!cvs) return;
    const ctx = cvs.getContext('2d');
    if (!ctx) return;

    const size = 150;
    cvs.width = size;
    cvs.height = size;
    const pxRes = 50;
    const heatmap = computeHeatmap(sources, freq, 15, pxRes); // 15m radius window

    const imgData = ctx.createImageData(pxRes, pxRes);
    for (let i = 0; i < heatmap.length; i++) {
      const val = heatmap[i] || 0;
      // Turbo/Viridis approximation (simple hot colormap)
      const r = Math.floor(255 * val);
      const g = Math.floor(255 * Math.pow(val, 2));
      const b = Math.floor(255 * Math.pow(val, 4));
      
      const idx = i * 4;
      imgData.data[idx] = r;
      imgData.data[idx + 1] = g;
      imgData.data[idx + 2] = b;
      imgData.data[idx + 3] = 255;
    }
    
    // Draw scaled
    const tempCanvas = window.document.createElement('canvas');
    tempCanvas.width = pxRes;
    tempCanvas.height = pxRes;
    tempCanvas.getContext('2d')!.putImageData(imgData, 0, 0);
    
    ctx.imageSmoothingEnabled = false;
    ctx.drawImage(tempCanvas, 0, 0, size, size);

  }, [sources, freq]);

  const handlePlace = () => {
    if (!document || !selectedSubId) return;

    const dt = document.deviceTypes.find(d => d.id === selectedSubId);
    if (!dt) return;

    updateDocument(draft => {
      for (let i = 0; i < sources.length; i++) {
        const newId = `${dt.slug}-${Math.floor(Math.random()*10000)}`;
        draft.devices.push({
          id: newId,
          deviceTypeId: dt.id,
          siteId: document.sites[0]?.id || 'site-1',
          name: `${dt.model} (${preset})`,
          status: 'planned'
        });
      }
    });
    setIsOpen(false);
  };

  if (!isOpen) {
    return (
      <button 
        style={{ position: 'absolute', bottom: 16, left: 16, zIndex: 10 }}
        className="m3-button"
        onClick={() => setIsOpen(true)}
      >
        {t('subarray.open')}
      </button>
    );
  }

  return (
    <div style={{
      position: 'absolute', bottom: 16, left: 16, zIndex: 20, 
      background: 'var(--copper-surface)', border: '1px solid var(--copper-outline)',
      padding: '16px', borderRadius: '8px', width: '400px',
      boxShadow: 'var(--md-sys-elevation-level-3)'
    }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 12 }}>
        <h3 style={{ margin: 0 }}>Sub Array Designer</h3>
        <button className="m3-button m3-button-text" onClick={() => setIsOpen(false)}>×</button>
      </div>

      <div style={{ marginBottom: '12px' }}>
        <label htmlFor="sub-model" style={{ display: 'block', fontSize: '12px', marginBottom: 4 }}>Subwoofer Model</label>
        <select id="sub-model" className="m3-input" value={selectedSubId} 
          onChange={e => setSelectedSubId(e.target.value)}
          style={{ width: '100%' }}
        >
          {availableSubs.map(dt => (
            <option key={dt.id} value={dt.id}>{dt.manufacturer} {dt.model}</option>
          ))}
        </select>
      </div>

      <div style={{ display: 'flex', gap: '8px', marginBottom: '12px' }}>
        <div style={{ flex: 1 }}>
          <label htmlFor="preset" style={{ display: 'block', fontSize: '12px', marginBottom: 4 }}>Preset</label>
          <select id="preset" className="m3-input" value={preset} 
            onChange={e => setPreset(e.target.value as ArrayPreset)}
            style={{ width: '100%' }}
          >
            <option value="Endfire">Endfire</option>
            <option value="Broadside">Broadside</option>
            <option value="Cardioid">Cardioid</option>
            <option value="Arc">Arc</option>
            <option value="Gradient">Gradient</option>
          </select>
        </div>
        <div style={{ width: '80px' }}>
          <label htmlFor="count" style={{ display: 'block', fontSize: '12px', marginBottom: 4 }}>Units</label>
          <input id="count" type="number" className="m3-input" value={count} onChange={e => setCount(Math.max(2, parseInt(e.target.value) || 2))}
            style={{ width: '100%' }}
          />
        </div>
      </div>


      <div style={{ display: 'flex', gap: '8px', marginBottom: '12px', alignItems: 'center' }}>
        <label style={{ display: 'flex', alignItems: 'center', fontSize: '12px', gap: '4px', cursor: 'pointer' }}>
          <input type="checkbox" checked={amplitudeShading} onChange={e => setAmplitudeShading(e.target.checked)} />
          Amplitude Shading
        </label>

        <div style={{ flex: 1, marginLeft: 'auto', display: 'flex', alignItems: 'center', gap: '4px' }}>
          <label htmlFor="delayTapering" style={{ fontSize: '12px' }}>Delay Taper (deg):</label>
          <input id="delayTapering" type="number" className="m3-input" value={delayTapering} onChange={e => setDelayTapering(e.target.value === '' ? '' : parseInt(e.target.value))} style={{ width: '60px' }} />
        </div>
      </div>

      <div style={{ display: 'flex', gap: '8px', marginBottom: '16px' }}>
        <div style={{ flex: 1 }}>
          <label htmlFor="freq" style={{ display: 'block', fontSize: '12px', marginBottom: 4 }}>Frequency (Hz)</label>
          <input id="freq" type="number" className="m3-input" value={freq} onChange={e => setFreq(parseInt(e.target.value) || 60)}
            style={{ width: '100%' }}
          />
        </div>
        <div style={{ flex: 1 }}>
          <label htmlFor="spacing" style={{ display: 'block', fontSize: '12px', marginBottom: 4 }}>Spacing (m)</label>
          <input 
            type="number" className="m3-input" placeholder="Auto"
            value={spacing} onChange={e => setSpacing(e.target.value === '' ? '' : parseFloat(e.target.value))}
            style={{ width: '100%' }}
          />
        </div>
      </div>

      <div style={{ display: 'flex', gap: '16px', marginBottom: '16px' }}>
        <div style={{ flex: 1, position: 'relative', height: '150px', border: '1px solid var(--copper-outline)', borderRadius: 4, overflow: 'hidden' }}>
          <svg width="100%" height="100%" viewBox="-1 -1 2 2" preserveAspectRatio="xMidYMid meet">
            {/* SVG Polar Plot */}
            <circle cx="0" cy="0" r="1" fill="none" stroke="var(--copper-outline)" strokeWidth="0.01" />
            <circle cx="0" cy="0" r="0.75" fill="none" stroke="var(--copper-outline)" strokeWidth="0.01" strokeDasharray="0.05 0.05" />
            <circle cx="0" cy="0" r="0.5" fill="none" stroke="var(--copper-outline)" strokeWidth="0.01" strokeDasharray="0.05 0.05" />
            
            <polygon 
              points={polarData.map(p => {
                // scale dB (-60 to 0) to radius (0 to 1)
                const r = Math.max(0, (p.db + 60) / 60);
                const rad = p.angle * Math.PI / 180;
                return `${Math.cos(rad) * r},${Math.sin(rad) * r}`;
              }).join(' ')}
              fill="var(--md-sys-color-primary-container)"
              stroke="var(--md-sys-color-primary)"
              strokeWidth="0.02"
            />
          </svg>
        </div>
        <div style={{ width: '150px', height: '150px', border: '1px solid var(--copper-outline)', borderRadius: 4, overflow: 'hidden' }}>
          <canvas ref={canvasRef}></canvas>
        </div>
      </div>

      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <div style={{ fontSize: '10px', color: 'var(--copper-text-secondary)' }}>
          Math by <a href="https://www.merlijnvanveen.nl/" target="_blank" rel="noreferrer" style={{ color: 'inherit' }}>Merlijn van Veen</a>
        </div>
        <button className="m3-button m3-button-primary" onClick={handlePlace} disabled={!selectedSubId}>
          {t('subarray.place')}
        </button>
      </div>
    </div>
  );
}

import { useBOM, useReferenceDesignators } from '../../store/selectors/derived';

export function BomView() {
  const bom = useBOM();
  const refs = useReferenceDesignators();

  return (
    <div style={{ padding: '2rem' }}>
      <h2>Bill of Materials</h2>
      <table style={{ width: '100%', borderCollapse: 'collapse' }}>
        <thead>
          <tr style={{ textAlign: 'left', borderBottom: '1px solid #ccc' }}>
            <th>Manufacturer</th>
            <th>Model</th>
            <th>Qty</th>
          </tr>
        </thead>
        <tbody>
          {bom.map((item, i) => (
            <tr key={i} style={{ borderBottom: '1px solid #eee' }}>
              <td>{item.manufacturer}</td>
              <td>{item.name}</td>
              <td>{item.quantity}</td>
            </tr>
          ))}
        </tbody>
      </table>

      <h2 style={{ marginTop: '2rem' }}>Reference Designators</h2>
      <ul>
        {Object.entries(refs).map(([id, des]) => (
          <li key={id}>{id}: {des as string}</li>
        ))}
      </ul>
    </div>
  );
}

import React from 'react';
import type { DesignDocument } from '../../model/schema';
import { exportCablesToCsv } from '../../export/csv';
import { useCableScheduleRows } from '../../store/selectors/derived';

interface CableScheduleViewProps {
  document: DesignDocument;
}

export const CableScheduleView: React.FC<CableScheduleViewProps> = ({ document }) => {
  const rows = useCableScheduleRows();

  const handleExport = () => {
    const csvContent = exportCablesToCsv(document);
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = window.document.createElement('a');
    link.href = url;
    link.setAttribute('download', 'cable-schedule.csv');
    window.document.body.appendChild(link);
    link.click();
    window.document.body.removeChild(link);
  };

  return (
    <div className="cable-schedule-view m3-content-padding" style={{ overflowY: 'auto', height: '100%' }}>
      <div className="header-actions" style={{ marginBottom: 16 }}>
        <button className="m3-button" onClick={handleExport}>Export to CSV</button>
      </div>
      <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left', background: 'var(--copper-surface)' }}>
        <thead>
          <tr style={{ borderBottom: '2px solid var(--copper-outline)' }}>
            <th style={{ padding: 8 }}>Cable ID</th>
            <th style={{ padding: 8 }}>Source</th>
            <th style={{ padding: 8 }}>Port</th>
            <th style={{ padding: 8 }}>Target</th>
            <th style={{ padding: 8 }}>Port</th>
            <th style={{ padding: 8 }}>Type</th>
            <th style={{ padding: 8 }}>Length (m)</th>
          </tr>
        </thead>
        <tbody>
          {rows.map(row => (
            <tr key={row.edgeId} style={{ borderBottom: '1px solid var(--copper-outline)' }}>
              <td style={{ padding: 8 }}>{row.cableId}</td>
              <td style={{ padding: 8 }}>{row.sourceDev}</td>
              <td style={{ padding: 8 }}>{row.sourcePort}</td>
              <td style={{ padding: 8 }}>{row.targetDev}</td>
              <td style={{ padding: 8 }}>{row.targetPort}</td>
              <td style={{ padding: 8 }}>{row.type}</td>
              <td style={{ padding: 8 }}>{row.lengthM}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

import { useEffect, useRef, CSSProperties } from 'react';
import { Graph } from '@antv/x6';
import { register, getProvider } from '@antv/x6-react-shape';
import { DeviceNodeComponent } from './nodes/DeviceNode';
import { LegendNodeComponent } from './nodes/LegendNode';
import { useDocumentStore } from '../../store/documentStore';

register({
  shape: 'device-node',
  width: 200,
  height: 100,
  component: DeviceNodeComponent,
});

register({
  shape: 'legend-node',
  width: 300,
  height: 250,
  component: LegendNodeComponent,
});

const ReactShapeProvider = getProvider();

export interface CanvasViewProps {
  nodes?: any[];
  edges?: any[];
  className?: string;
  style?: CSSProperties;
  enableWiring?: boolean;
}

import { getPortSignature } from '../../utils/portSignature';
import { canConnect } from '../../model/connector-accepts';
import { useState } from 'react';

const defaultCanvasStyle: CSSProperties = {
  width: '100%',
  height: '100%',
  minHeight: '400px',
  position: 'relative'
};

export function CanvasView({
  nodes = [],
  edges = [],
  style,
  enableWiring = false,
}: CanvasViewProps) {
  const setSelectedIds = useDocumentStore(state => state.setSelectedIds);
  const updateDocument = useDocumentStore(state => state.updateDocument);
  const document = useDocumentStore(state => state.document);
  const containerRef = useRef<HTMLDivElement>(null);
  const graphRef = useRef<Graph | null>(null);

  const [rejectedDrop, setRejectedDrop] = useState<{ srcDevice: string; tgtDevice: string; srcPortType: string; tgtPortType: string; suggestedAdapters: string[] } | null>(null);

  useEffect(() => {
    if (!containerRef.current) return;

    const graph = new Graph({
      container: containerRef.current,
      autoResize: true,
      background: { color: 'var(--md-sys-color-surface-container-lowest)' },
      panning: true,
      mousewheel: { enabled: true, modifiers: ['ctrl', 'meta'] },
      interacting: { nodeMovable: enableWiring, edgeMovable: enableWiring },
      connecting: {
        router: {
          name: 'normal',
        },
        connector: { name: 'rounded', args: { radius: 8 } },
        allowBlank: false,
        allowLoop: false,
        allowNode: false,
        validateConnection({ sourceMagnet, targetMagnet, sourceCell, targetCell }) {
          if (!sourceMagnet || !targetMagnet) return false;
          if (sourceCell === targetCell) return false;
          const srcPortGroup = sourceMagnet.getAttribute('port-group');
          const tgtPortGroup = targetMagnet.getAttribute('port-group');
          if (srcPortGroup === tgtPortGroup) return false; // Prevent in->in or out->out

          // Additional logic for B102: Check connector/signal class compatibility
          // For now just prevent same-group wiring. Full check happens at drop.
          return true;
        }
      }
    });

    graphRef.current = graph;

    return () => {
      graph.dispose();
    };
  }, [enableWiring]);

  useEffect(() => {
    const graph = graphRef.current;
    if (!graph) return;

    const x6Nodes = nodes.map(n => ({
      ...n,
      ports: {
        ...n.ports,
        groups: {
          in: {
            position: 'absolute',
            attrs: {
              circle: { r: 4, magnet: true, stroke: 'var(--md-sys-color-outline)', fill: 'var(--md-sys-color-surface)', strokeWidth: 1 }
            }
          },
          out: {
            position: 'absolute',
            attrs: {
              circle: { r: 4, magnet: true, stroke: 'var(--md-sys-color-outline)', fill: 'var(--md-sys-color-surface)', strokeWidth: 1 }
            }
          }
        }
      }
    }));

    const x6Edges = edges.map(e => ({
      ...e,
      tools: ['vertices', 'segments'],
      attrs: {
        line: {
          stroke: 'var(--md-sys-color-outline)',
          strokeWidth: 2,
          targetMarker: { name: 'block', width: 6, height: 6 }
        }
      }
    }));

    graph.fromJSON({ nodes: x6Nodes, edges: x6Edges });
    graph.centerContent();

    graph.on('cell:click', ({ cell }) => {
      setSelectedIds([cell.id]);
    });

    graph.on('blank:click', () => {
      setSelectedIds([]);
    });

    graph.on('edge:connected', ({ isNew, edge }: any) => {
      if (!isNew || !document) return;
      const source = edge.getSource();
      const target = edge.getTarget();

      if (source.cell && target.cell && source.port && target.port) {
        // B102: Connect Assist Validation
        const srcSig = getPortSignature(document, source.cell, source.port);
        const tgtSig = getPortSignature(document, target.cell, target.port);

        if (srcSig && tgtSig && !canConnect(srcSig, tgtSig)) {
          // Reject
          edge.remove();

          // Suggest adapters (naive mock for Dante etc)
          const suggestedAdapters: string[] = [];
          if (srcSig.signalType === 'AUDIO' && tgtSig.signalType === 'NETWORK') {
            suggestedAdapters.push('Dante AVIO Adapter');
          } else if (srcSig.signalType === 'VIDEO' && tgtSig.signalType === 'NETWORK') {
            suggestedAdapters.push('SDVoE Encoder');
          }

          setRejectedDrop({
            srcDevice: document.devices.find(d => d.id === source.cell)?.name || source.cell,
            tgtDevice: document.devices.find(d => d.id === target.cell)?.name || target.cell,
            srcPortType: srcSig.connectorType,
            tgtPortType: tgtSig.connectorType,
            suggestedAdapters
          });
          return;
        }

        updateDocument(draft => {
          draft.cables.push({
            id: edge.id,
            terminations: [
              { deviceId: source.cell, portRef: { name: source.port.split('-').pop() || source.port, kind: source.port.split('-')[0] || 'interface' } as any },
              { deviceId: target.cell, portRef: { name: target.port.split('-').pop() || target.port, kind: target.port.split('-')[0] || 'interface' } as any }
            ],
            type: 'cat6',
            signalType: srcSig?.signalType || 'ETHERNET',
            status: 'planned'
          });
        });
      }
    });

  }, [nodes, edges, setSelectedIds, document, updateDocument]);

  return (
    <div className="copper-canvas-container" style={{ ...defaultCanvasStyle, ...style }} data-testid="copper-canvas-view">
      <div ref={containerRef} style={{ width: '100%', height: '100%' }} />
      <ReactShapeProvider />
      {rejectedDrop && (
        <div style={{
          position: 'absolute', top: '50%', left: '50%', transform: 'translate(-50%, -50%)',
          background: 'var(--copper-surface-container-high)', border: '1px solid var(--copper-outline)', padding: 24, borderRadius: 12,
          boxShadow: 'var(--md-sys-elevation-level-4)', zIndex: 10000, color: 'var(--copper-on-surface)'
        }}>
          <h3 style={{ margin: '0 0 16px 0', color: 'var(--copper-error)' }}>Incompatible Connection</h3>
          <p style={{ margin: '0 0 16px 0' }}>
            Cannot connect <b>{rejectedDrop.srcPortType}</b> ({rejectedDrop.srcDevice}) to <b>{rejectedDrop.tgtPortType}</b> ({rejectedDrop.tgtDevice}).
          </p>
          {rejectedDrop.suggestedAdapters.length > 0 && (
            <div style={{ marginBottom: 16 }}>
              <strong style={{ display: 'block', marginBottom: 8 }}>Suggested Adapters:</strong>
              {rejectedDrop.suggestedAdapters.map((a: string, i: number) => (
                <button key={i} style={{ padding: '4px 12px', background: 'var(--copper-primary-container)', color: 'var(--copper-on-primary-container)', border: 'none', borderRadius: 4, marginRight: 8 }}>
                  {a}
                </button>
              ))}
            </div>
          )}
          <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
            <button onClick={() => setRejectedDrop(null)} style={{ padding: '8px 16px', background: 'var(--copper-primary)', color: 'var(--copper-on-primary)', border: 'none', borderRadius: 8, cursor: 'pointer' }}>
              Dismiss
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

