import { useParams, useNavigate } from 'react-router-dom';
import { ConnectedCanvasView } from '../../shell/index';
import { SceneView } from '../scene/SceneView';
import { FloorplanMode } from './FloorplanMode';
import { CableRoutingMode } from './CableRoutingMode';
import { useDocumentStore } from '../../store/documentStore';
import { ProblemsPanel } from '../../ui/problems/ProblemsPanel';
import { exportToDxf } from '../../export/dxf';

export function DesignWorkspace() {
  const { mode } = useParams();
  const navigate = useNavigate();
  const document = useDocumentStore(state => state.document);

  const currentMode = mode || 'schematic';

  const handleExportDXF = () => {
    if (!document) return;
    const nodes = document.devices.map((d: any) => ({
      id: d.name || d.id,
      position: { x: d.geometry?.x ?? 0, y: d.geometry?.y ?? 0 },
      initialWidth: 200,
      initialHeight: 100
    }));
    const edges = document.cables.map((c: any) => ({
      source: document.devices.find((d: any) => d.id === c.terminations[0].deviceId)?.name || c.terminations[0].deviceId,
      target: document.devices.find((d: any) => d.id === c.terminations[1].deviceId)?.name || c.terminations[1].deviceId,
    }));
    const dxfStr = exportToDxf(nodes, edges);
    const blob = new Blob([dxfStr], { type: 'application/dxf' });
    const url = URL.createObjectURL(blob);
    const a = window.document.createElement('a');
    a.href = url;
    a.download = 'design.dxf';
    a.click();
  };

  const modes = [
    { id: 'schematic', label: 'Schematic' },
    { id: 'floorplan', label: 'Floorplan' },
    { id: 'routing', label: 'Cable Routing' },
    { id: '3d', label: '3D Scene' }
  ];

  if (!document) {
    return <div className="m3-content-padding">Loading document...</div>;
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100vh', width: '100vw', overflow: 'hidden' }}>
      <div style={{ display: 'flex', justifyContent: 'center', padding: '8px', background: 'var(--copper-surface-container)', borderBottom: '1px solid var(--copper-outline-variant)' }}>
        <div style={{ display: 'flex', background: 'var(--copper-surface)', borderRadius: 8, overflow: 'hidden', border: '1px solid var(--copper-outline)' }}>
          {modes.map((m, idx) => {
            const isActive = currentMode === m.id;
            return (
              <button
                key={m.id}
                onClick={() => navigate('/design/' + m.id)}
                style={{
                  padding: '8px 16px',
                  background: isActive ? 'var(--copper-secondary-container)' : 'transparent',
                  color: isActive ? 'var(--copper-on-secondary-container)' : 'var(--copper-on-surface)',
                  border: 'none',
                  borderRight: idx < modes.length - 1 ? '1px solid var(--copper-outline)' : 'none',
                  cursor: 'pointer',
                  fontWeight: isActive ? 600 : 400
                }}
              >
                {m.label}
              </button>
            );
          })}
        </div>
        <div style={{ marginLeft: '16px', display: 'flex', alignItems: 'center' }}>
          <button 
            onClick={handleExportDXF}
            style={{ padding: '8px 16px', background: 'var(--copper-primary)', color: 'var(--copper-on-primary)', border: 'none', borderRadius: 8, cursor: 'pointer' }}
          >
            Export DXF
          </button>
        </div>
      </div>

      <div style={{ flex: 1, position: 'relative' }}>
        {document.devices.length === 0 && currentMode === 'schematic' && (
          <div style={{
            position: 'absolute', top: 0, left: 0, right: 0, bottom: 0,
            background: 'var(--copper-surface-container-lowest)', zIndex: 100,
            display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center'
          }}>
            <h2 style={{ color: 'var(--copper-on-surface)' }}>Design from Intent</h2>
            <p style={{ color: 'var(--copper-on-surface-variant)', marginBottom: 32 }}>Choose a generative starting point</p>
            <div style={{ display: 'flex', gap: 16 }}>
              <div style={{ padding: 24, background: 'var(--copper-surface-container)', borderRadius: 12, border: '1px solid var(--copper-outline)', cursor: 'pointer' }}>
                <h3>100V Paging Zone</h3>
                <p style={{ color: 'var(--copper-on-surface-variant)' }}>Amp + 8 Ceiling Speakers</p>
              </div>
              <div style={{ padding: 24, background: 'var(--copper-surface-container)', borderRadius: 12, border: '1px solid var(--copper-outline)', cursor: 'pointer' }}>
                <h3>Boardroom VC</h3>
                <p style={{ color: 'var(--copper-on-surface-variant)' }}>DSP, Amps, PTZ Camera, Mics</p>
              </div>
            </div>
          </div>
        )}
        {currentMode === 'schematic' && <ConnectedCanvasView />}
        {currentMode === 'floorplan' && <FloorplanMode />}
        {currentMode === 'routing' && <CableRoutingMode />}
        {currentMode === '3d' && <SceneView />}
        <ProblemsPanel />
      </div>
    </div>
  );
}

import React, { useState, useRef } from 'react';
import { useDocumentStore } from '../../store/documentStore';

function DraggableDevice({ device, geometry, updateGeometry }: { device: any, geometry: any, updateGeometry: (id: string, pos: {x: number, y: number}) => void }) {
  const [isDragging, setIsDragging] = useState(false);
  const pos = geometry?.position || { x: 0, y: 0 };
  const ref = useRef<HTMLDivElement>(null);

  const handlePointerDown = (e: React.PointerEvent) => {
    e.stopPropagation();
    e.currentTarget.setPointerCapture(e.pointerId);
    setIsDragging(true);
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!isDragging) return;
    e.stopPropagation();
    const newX = pos.x + e.movementX;
    const newY = pos.y + e.movementY;
    updateGeometry(device.id, { x: newX, y: newY });
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    e.stopPropagation();
    e.currentTarget.releasePointerCapture(e.pointerId);
    setIsDragging(false);
  };

  return (
    <div
      ref={ref}
      title={device.name}
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerUp}
      onPointerCancel={handlePointerUp}
      style={{
        position: 'absolute',
        left: pos.x,
        top: pos.y,
        width: 32,
        height: 32,
        transform: 'translate(-50%, -50%)',
        background: 'var(--copper-primary)',
        color: 'var(--copper-on-primary)',
        borderRadius: '50%',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        cursor: isDragging ? 'grabbing' : 'grab',
        userSelect: 'none',
        boxShadow: 'var(--md-sys-elevation-level-1)',
        zIndex: isDragging ? 10 : 1,
        fontSize: '0.75rem',
        fontWeight: 'bold'
      }}
    >
      {device.name?.substring(0, 2) || device.id.substring(0, 2)}
    </div>
  );
}

export function FloorplanMode() {
  const document = useDocumentStore(state => state.document);
  const updateDocument = useDocumentStore(state => state.updateDocument);
  const [mode, setMode] = useState<'select' | 'viewer' | 'participant' | 'task'>('select');
  const [drawingRect, setDrawingRect] = useState<{ startX: number, startY: number, endX: number, endY: number } | null>(null);

  if (!document) return null;

  const handleUpdateGeometry = (deviceId: string, position: {x: number, y: number}) => {
    if (mode !== 'select') return; // Don't drag if drawing
    updateDocument((draft: any) => {
      if (!draft.geometry) draft.geometry = {};
      if (!draft.geometry[deviceId]) draft.geometry[deviceId] = {};
      draft.geometry[deviceId].position = position;
    });
  };

  const handleBackgroundPointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    if (mode === 'select') return;
    const rect = e.currentTarget.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    setDrawingRect({ startX: x, startY: y, endX: x, endY: y });
    (e.target as HTMLElement).setPointerCapture(e.pointerId);
  };

  const handleBackgroundPointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!drawingRect || mode === 'select') return;
    const rect = e.currentTarget.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    setDrawingRect(prev => prev ? { ...prev, endX: x, endY: y } : null);
  };

  const handleBackgroundPointerUp = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!drawingRect || mode === 'select') return;
    (e.target as HTMLElement).releasePointerCapture(e.pointerId);

    const x = Math.min(drawingRect.startX, drawingRect.endX);
    const y = Math.min(drawingRect.startY, drawingRect.endY);
    const width = Math.abs(drawingRect.endX - drawingRect.startX);
    const height = Math.abs(drawingRect.endY - drawingRect.startY);

    setDrawingRect(null);
    setMode('select');

    if (width > 10 && height > 10) {
      updateDocument((draft: any) => {
        if (!draft.zones) draft.zones = [];
        if (!draft.geometry) draft.geometry = {};

        const zoneId = `zone-${crypto.randomUUID().substring(0, 8)}`;
        draft.zones.push({
          id: zoneId,
          name: `New ${mode} zone`,
          type: mode
        });

        draft.geometry[zoneId] = {
          position: { x, y },
          size: { width, height }
        };
      });
    }
  };

  const locations = document.locations || [];
  const devices = document.devices || [];
  const zones = document.zones || [];

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
      <div style={{ padding: '8px', borderBottom: '1px solid var(--md-sys-color-outline-variant)', background: 'var(--md-sys-color-surface)' }}>
        <button onClick={() => setMode('select')} style={{ fontWeight: mode === 'select' ? 'bold' : 'normal', marginRight: 8 }}>Select / Move</button>
        <button onClick={() => setMode('viewer')} style={{ fontWeight: mode === 'viewer' ? 'bold' : 'normal', marginRight: 8 }}>+ Viewer Zone</button>
        <button onClick={() => setMode('participant')} style={{ fontWeight: mode === 'participant' ? 'bold' : 'normal', marginRight: 8 }}>+ Participant Zone</button>
        <button onClick={() => setMode('task')} style={{ fontWeight: mode === 'task' ? 'bold' : 'normal', marginRight: 8 }}>+ Task Zone</button>
      </div>

      <div 
        style={{ position: 'relative', flex: 1, overflow: 'auto', background: 'var(--copper-surface-container-lowest)', cursor: mode === 'select' ? 'default' : 'crosshair' }}
        onPointerDown={handleBackgroundPointerDown}
        onPointerMove={handleBackgroundPointerMove}
        onPointerUp={handleBackgroundPointerUp}
      >
        {/* Rooms Layer */}
        {locations.map(loc => {
          const layout = (loc as any).layout || { x: 0, y: 0, width: 400, height: 300 };
          return (
            <div
              key={loc.id}
              style={{
                position: 'absolute',
                left: layout.x,
                top: layout.y,
                width: layout.width,
                height: layout.height,
                border: '2px solid var(--copper-outline)',
                background: 'var(--copper-surface-container)',
                opacity: 0.8,
                pointerEvents: 'none'
              }}
            >
              <div style={{ padding: '8px', fontWeight: 'bold', color: 'var(--copper-on-surface)' }}>
                {loc.name || loc.id}
              </div>
            </div>
          );
        })}

        {/* Zones Layer */}
        {zones.map(zone => {
          const geo = document.geometry?.[zone.id];
          if (!geo || !geo.position || !geo.size) return null;
          let color = 'rgba(0, 0, 255, 0.2)';
          if (zone.type === 'participant') color = 'rgba(0, 255, 0, 0.2)';
          if (zone.type === 'task') color = 'rgba(255, 165, 0, 0.2)';

          return (
            <div
              key={zone.id}
              style={{
                position: 'absolute',
                left: geo.position.x,
                top: geo.position.y,
                width: geo.size.width,
                height: geo.size.height,
                background: color,
                border: `1px solid ${color.replace('0.2', '0.8')}`,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                pointerEvents: 'none'
              }}
            >
              <span style={{ fontWeight: 'bold', color: '#333' }}>{zone.name}</span>
            </div>
          );
        })}

        {/* Drawing Rect */}
        {drawingRect && (
          <div style={{
            position: 'absolute',
            left: Math.min(drawingRect.startX, drawingRect.endX),
            top: Math.min(drawingRect.startY, drawingRect.endY),
            width: Math.abs(drawingRect.endX - drawingRect.startX),
            height: Math.abs(drawingRect.endY - drawingRect.startY),
            background: 'rgba(0, 150, 255, 0.3)',
            border: '1px dashed #0096ff',
            pointerEvents: 'none'
          }} />
        )}

        {/* Devices Layer */}
        {devices.map(device => (
          <DraggableDevice
            key={device.id}
            device={device}
            geometry={document.geometry?.[device.id]}
            updateGeometry={handleUpdateGeometry}
          />
        ))}
      </div>
    </div>
  );
}

import { useState, useMemo } from 'react';
import { useDocumentStore } from '../../store/documentStore';

export function DevicePalette() {
  const [searchTerm, setSearchTerm] = useState('');
  const document = useDocumentStore((state) => state.document);
  const updateDocument = useDocumentStore((state) => state.updateDocument);

  const deviceTypes = document?.deviceTypes || [];

  const filteredTypes = useMemo(() => {
    if (!searchTerm.trim()) return deviceTypes;

    const search = searchTerm.toLowerCase();
    const terms = search.split(/\s+/).filter(Boolean);

    return deviceTypes.filter((dt) => {
      const searchSpace = [
        dt.manufacturer,
        dt.model,
        dt.id,
        dt.description,
        dt.customFields?.acoustics?.category,
        dt.customFields?.acoustics?.type,
        dt.customFields?.acoustics?.impedance ? String(dt.customFields.acoustics.impedance) + 'Ohm ' + String(dt.customFields.acoustics.impedance) + 'O' : '',
        dt.customFields?.acoustics?.wattage_rms ? String(dt.customFields.acoustics.wattage_rms) + 'W' : ''
      ].filter(Boolean).join(' ').toLowerCase();

      return terms.every(term => searchSpace.includes(term));
    });
  }, [deviceTypes, searchTerm]);

  const handleAddDevice = (deviceTypeId: string) => {
    updateDocument((draft) => {
      const siteId = draft.sites?.[0]?.id || 'default-site';
      const dt = (draft.deviceTypes || []).find(d => d.id === deviceTypeId);

      const baseName = dt ? (dt.model || deviceTypeId) : deviceTypeId;
      const newId = 'dev-' + Math.random().toString(36).substring(2, 9);

      draft.devices.push({
        id: newId,
        deviceTypeId,
        siteId,
        status: 'planned',
        name: baseName + ' (New)'
      });
    });
  };

  if (!document) {
    return <div data-testid="device-palette-empty">No document loaded</div>;
  }

  return (
    <div style={{ width: 280, borderRight: '1px solid var(--md-sys-color-outline-variant)', background: 'var(--md-sys-color-surface)', display: 'flex', flexDirection: 'column', zIndex: 10 }}>
      <div style={{ padding: 16, borderBottom: '1px solid var(--md-sys-color-outline-variant)' }}>
        <h3 className="m3-title-medium" style={{ margin: '0 0 16px 0' }}>Device Palette</h3>
        <input 
          type="text"
          className="m3-text-field"
          style={{ width: '100%', padding: '8px 12px', borderRadius: 4, border: '1px solid var(--md-sys-color-outline)' }}
          placeholder="Search (e.g. '8O 200W ceiling')"
          value={searchTerm}
          onChange={e => setSearchTerm(e.target.value)}
        />
      </div>

      <div style={{ flex: 1, overflowY: 'auto', padding: 8 }}>
        <p className="m3-label-small" style={{ margin: '0 8px 8px 8px', color: 'var(--md-sys-color-on-surface-variant)' }}>
          {filteredTypes.length} types found
        </p>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
          {filteredTypes.map(dt => (
            <div 
              key={dt.id}
              role="button" tabIndex={0} onKeyDown={(e) => { if (e.key === 'Enter') handleAddDevice(dt.id); }} onClick={() => handleAddDevice(dt.id)}
              style={{
                padding: 12,
                borderRadius: 8,
                background: 'var(--md-sys-color-surface-container-low)',
                cursor: 'pointer',
                border: '1px solid transparent'
              }}
              onMouseEnter={e => e.currentTarget.style.border = '1px solid var(--md-sys-color-primary)'}
              onMouseLeave={e => e.currentTarget.style.border = '1px solid transparent'}
            >
              <div className="m3-label-medium" style={{ fontWeight: 600 }}>{dt.manufacturer} {dt.model}</div>
              <div className="m3-body-small" style={{ color: 'var(--md-sys-color-on-surface-variant)', marginTop: 4 }}>
                {dt.customFields?.acoustics?.type ? String(dt.customFields.acoustics.type) + ' ' : ''}
                {dt.customFields?.acoustics?.category ? String(dt.customFields.acoustics.category) + ' ' : ''}
                {dt.customFields?.acoustics?.wattage_rms ? String(dt.customFields.acoustics.wattage_rms) + 'W ' : ''}
                {dt.customFields?.acoustics?.impedance ? String(dt.customFields.acoustics.impedance) + 'Ω ' : ''}
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

import React from 'react';
import { DesignDocument, Device } from '../../model/schema';
import { computeRackElevations } from '../../model/rack-view';
import { useDocumentStore } from '../../store';
import { validateRackFit } from '../../validation/rack-fit';


interface RackElevationViewProps {
  doc: DesignDocument;
  geometryMap: Record<string, unknown>;
  selectedRackId: string;
}

export const RackElevationView: React.FC<RackElevationViewProps> = ({
  doc,
  geometryMap,
  selectedRackId,
}) => {
  const updateDocument = useDocumentStore(s => s.updateDocument);
  const elevations = computeRackElevations(doc, geometryMap);
  const unassignedDevices = doc.devices.filter(d => !d.rackId);

  const elevation = elevations.find((e) => e.rackId === selectedRackId);

  if (!elevation) {
    return <div data-testid="rack-not-found">Rack not found</div>;
  }


  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDrop = (e: React.DragEvent, uNum: number, face: 'front' | 'rear') => {
    e.preventDefault();
    const deviceId = e.dataTransfer.getData('text/plain');
    if (!deviceId) return;

    const device = doc.devices.find(d => d.id === deviceId);
    if (!device) return;

    const rack = doc.racks.find(r => r.id === selectedRackId);
    if (!rack) return;



    const tempDevices = doc.devices.map(d => 
      d.id === deviceId 
        ? { ...d, rackId: rack.id, position: uNum, face } 
        : d
    );

    const errors = validateRackFit({ ...doc, devices: tempDevices } as any).findings;

    if (errors.length > 0) {
      return;
    }

    updateDocument(draft => { const d = draft.devices.find(x => x.id === deviceId);
      if (d) {
        d.rackId = rack.id;
        d.position = uNum;
        d.face = face;

        const draftAny = draft as unknown as { geometry?: Record<string, unknown> };
        const g = draftAny.geometry || {};
        g[deviceId] = {
          ...(g[deviceId] || {}),
          rack_position: uNum,
          rack_face: face,
        };
        draftAny.geometry = g;
      }
    });
  };

  const uNumbers = [];
  for (let u = Math.floor(elevation.totalU); u >= 1; u--) {
    uNumbers.push(u);
  }

  const renderSlot = (uNum: number, face: 'front' | 'rear') => {
    const slotMain = elevation.slots.find(s => s.uNumber === uNum);
    const slotHalf = elevation.slots.find(s => s.uNumber === uNum + 0.5);

    const renderDeviceBlock = (device: Device) => (
      <div 
        key={device.id} 
        draggable
        onDragStart={(e) => {
          e.dataTransfer.setData('text/plain', device.id);
        }}
        style={{ 
          backgroundColor: 'var(--md-sys-color-primary-container)', 
          border: '1px solid var(--md-sys-color-primary)', 
          padding: '2px', 
          margin: '1px',
          fontSize: '12px',
          flex: 1,
          overflow: 'hidden',
          whiteSpace: 'nowrap',
          textOverflow: 'ellipsis'
        }}
        data-testid={`device-${device.id}-${face}`}
        title={device.name}
      >
        {device.name}
      </div>
    );

    const mainDevices = slotMain ? slotMain[face] : [];
    const halfDevices = slotHalf ? slotHalf[face] : [];

    return (
      <div key={`${face}-${uNum}`} style={{ display: 'flex', borderBottom: '1px solid var(--md-sys-color-outline-variant)', minHeight: '40px' }} data-testid={`slot-${uNum}-${face}`} onDragOver={handleDragOver} onDrop={(e) => handleDrop(e, uNum, face)}>
        <div style={{ width: '40px', borderRight: '1px solid var(--md-sys-color-outline-variant)', display: 'flex', alignItems: 'center', justifyContent: 'center', backgroundColor: 'var(--md-sys-color-surface-container-high)', fontWeight: 'bold' }}>
          {uNum}U
        </div>
        <div style={{ flex: 1, display: 'flex', flexDirection: 'column' }}>
          <div style={{ flex: 1, display: 'flex', minHeight: '20px', borderBottom: '1px dashed var(--md-sys-color-outline-variant)' }}>
            {mainDevices.length > 0 
              ? mainDevices.map(d => renderDeviceBlock(d))
              : <div style={{ flex: 1 }} data-testid={`empty-${uNum}-main-${face}`} />
            }
          </div>
          <div style={{ flex: 1, display: 'flex', minHeight: '20px' }}>
            {halfDevices.length > 0 
              ? halfDevices.map(d => renderDeviceBlock(d))
              : <div style={{ flex: 1 }} data-testid={`empty-${uNum}-half-${face}`} />
            }
          </div>
        </div>
      </div>
    );
  };

  return (
    <div style={{ display: 'flex', gap: '20px', padding: '20px', fontFamily: 'sans-serif' }}>
      <div style={{ flex: 1, border: '2px solid var(--md-sys-color-outline)', borderRadius: '4px', overflow: 'hidden' }}>
        <h3 style={{ textAlign: 'center', backgroundColor: 'var(--md-sys-color-inverse-surface)', color: 'var(--md-sys-color-inverse-on-surface)', margin: 0, padding: '10px' }}>Unassigned Devices</h3>
        <div style={{ display: 'flex', flexDirection: 'column', padding: '10px', gap: '5px' }} data-testid="unassigned-list">
          {unassignedDevices.map(device => (
             <div 
               key={device.id} 
               draggable
               onDragStart={(e) => e.dataTransfer.setData('text/plain', device.id)}
               style={{ backgroundColor: 'var(--md-sys-color-primary-container)', border: '1px solid var(--md-sys-color-primary)', padding: '5px', fontSize: '12px', cursor: 'grab' }}
               data-testid={`unassigned-${device.id}`}
             >
               {device.name || device.id}
             </div>
          ))}
        </div>
      </div>

      <div style={{ flex: 1, border: '2px solid var(--md-sys-color-outline)', borderRadius: '4px', overflow: 'hidden' }}>
        <h3 style={{ textAlign: 'center', backgroundColor: 'var(--md-sys-color-inverse-surface)', color: 'var(--md-sys-color-inverse-on-surface)', margin: 0, padding: '10px' }}>Front Face</h3>
        <div style={{ display: 'flex', flexDirection: 'column' }}>
          {uNumbers.map(u => renderSlot(u, 'front'))}
        </div>
      </div>

      <div style={{ flex: 1, border: '2px solid var(--md-sys-color-outline)', borderRadius: '4px', overflow: 'hidden' }}>
        <h3 style={{ textAlign: 'center', backgroundColor: 'var(--md-sys-color-inverse-surface)', color: 'var(--md-sys-color-inverse-on-surface)', margin: 0, padding: '10px' }}>Rear Face</h3>
        <div style={{ display: 'flex', flexDirection: 'column' }}>
          {uNumbers.map(u => renderSlot(u, 'rear'))}
        </div>
      </div>
    </div>
  );
};

import { Canvas, useThree } from '@react-three/fiber';
import { OrbitControls, Html } from '@react-three/drei';
import { useDocumentStore } from '../../store';
import { RoomVolume } from './RoomVolume';
import { RackVolume } from './RackVolume';
import { CoverageOverlay } from './CoverageOverlay';

import { GLTFExporter } from 'three/examples/jsm/exporters/GLTFExporter.js';

function ExportButton() {
  const { scene } = useThree();

  const handleExport = () => {
    const exporter = new GLTFExporter();
    exporter.parse(
      scene,
      (gltf) => {
        const output = JSON.stringify(gltf, null, 2);
        const blob = new Blob([output], { type: 'text/plain' });
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.style.display = 'none';
        link.href = url;
        link.download = 'scene.gltf';
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(url);
      },
      (error) => {
        console.error('An error happened during glTF export:', error);
      }
    );
  };

  return (
    <Html style={{ position: 'absolute', top: 10, left: 10 }}>
      <button 
        onClick={handleExport}
        className="bg-blue-600 hover:bg-blue-700 text-white px-3 py-1 rounded text-sm shadow-md"
      >
        Download glTF
      </button>
    </Html>
  );
}

export function SceneView() {
  const document = useDocumentStore((state) => state.document);
  const locations = document?.locations;
  const racks = document?.racks;
  const devices = document?.devices;

  return (
    <div style={{ width: '100%', height: '100vh', background: 'var(--md-sys-color-surface-container-lowest)' }}>
      <Canvas camera={{ position: [5, 5, 5] }}>
        <ambientLight intensity={0.5} />
        <directionalLight position={[10, 10, 10]} intensity={1} />

        <OrbitControls />
        <ExportButton />

        {locations?.map((loc) => (
          <RoomVolume key={loc.id} location={loc} />
        ))}

        <CoverageOverlay />

        {racks?.map((rack, i) => {
          const rackDevices = devices?.filter((d) => d.rackId === rack.id) ?? [];
          return (
            <RackVolume
              key={rack.id}
              rack={rack}
              devices={rackDevices}
              position={[i * 2, 0, 0]}
            />
          );
        })}

        {/* Free-floating devices with geometry (B108 floorplan sync) */}
        {devices?.filter(d => !d.rackId && document?.geometry?.[d.id]).map(device => {
          const pos = document?.geometry?.[device.id]?.position;
          if (!pos) return null;
          // Scale from floorplan pixels to 3D units (same scale as RoomVolume: 0.01)
          const scale = 0.01;
          const x = pos.x * scale;
          const z = pos.y * scale;
          const h = 1.0; // Place it a bit above ground or at specific Z if known

          return (
            <group key={device.id} position={[x, h, z]}>
              <mesh>
                <boxGeometry args={[0.3, 0.3, 0.3]} />
                <meshStandardMaterial color='var(--copper-primary)' />
              </mesh>
              <Html distanceFactor={10} position={[0, 0.4, 0]} transform>
                <div style={{ background: 'var(--copper-surface)', color: 'var(--copper-on-surface)', padding: '2px 4px', borderRadius: 4, fontSize: 10, whiteSpace: 'nowrap' }}>
                  {device.name}
                </div>
              </Html>
            </group>
          );
        })}
      </Canvas>
    </div>
  );
}
